SourceCode.Declaration:
/// <summary>
/// HSMobileOpsDeviceWorkSvc request. ItemsJson is a JSON array of the device's unsent work (Key, UserName, WarehouseId, Kind, Reference, Summary, LineCount, CapturedMs, Payload); with Complete it is the device's whole set and rows not in it are removed. ClearDeviceId removes UserName's rows of another device - work restored from it.
/// </summary>
[DataContractAttribute]
class HSMobileOpsDeviceWorkRequest
{
    DataAreaId dataAreaId;
    str        deviceId;
    str        userName;
    str        appVersion;
    str        deviceModel;
    str        itemsJson;
    boolean    complete;
    str        clearDeviceId;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('DeviceId')]
public str parmDeviceId(str _value = deviceId)
{
    deviceId = _value;
    return deviceId;
}

[DataMemberAttribute('UserName')]
public str parmUserName(str _value = userName)
{
    userName = _value;
    return userName;
}

[DataMemberAttribute('AppVersion')]
public str parmAppVersion(str _value = appVersion)
{
    appVersion = _value;
    return appVersion;
}

[DataMemberAttribute('DeviceModel')]
public str parmDeviceModel(str _value = deviceModel)
{
    deviceModel = _value;
    return deviceModel;
}

[DataMemberAttribute('ItemsJson')]
public str parmItemsJson(str _value = itemsJson)
{
    itemsJson = _value;
    return itemsJson;
}

[DataMemberAttribute('Complete')]
public boolean parmComplete(boolean _value = complete)
{
    complete = _value;
    return complete;
}

[DataMemberAttribute('ClearDeviceId')]
public str parmClearDeviceId(str _value = clearDeviceId)
{
    clearDeviceId = _value;
    return clearDeviceId;
}
